/* Every copy of her (big intro, mini, avatar, rider) needs its own gradient / clip ids. */
function phoenixSVG(id){
  var inner = SVG_ORIG.replace(/^<svg[^>]*>/,'').replace(/<\/svg>\s*$/,'');
  inner = inner.replace(/id="([a-zA-Z0-9]+)"/g, function(m,x){ return 'id="'+x+'-'+id+'"'; })
               .replace(/url\(#([a-zA-Z0-9]+)\)/g, function(m,x){ return 'url(#'+x+'-'+id+')'; });
  return '<g id="'+id+'" class="body">'+inner+'</g>';
}
