function cleanSpeech(t){ return String(t).replace(/[\uD800-\uDFFF]./g,'').replace(/[\u2600-\u27BF\uFE0F\u200D]/g,'').replace(/\s+/g,' ').trim(); }
var VPREF=[/google us english/i,/\bsamantha\b/i,/\baria\b/i,/\bjenny\b/i,/\bava\b/i,/\bzira\b/i,/\ballison\b/i,/english \(united states\)/i,/en[-_]us/i,/female/i];
function pickVoice(){ var vs=[]; try{ vs=window.speechSynthesis.getVoices()||[]; }catch(e){} var us=vs.filter(function(v){ return /^en[-_]?us/i.test(v.lang)||/united states/i.test(v.name); }); var pool=us.length?us:vs.filter(function(v){ return /^en/i.test(v.lang)&&!/gb|uk|au|ie|za|in/i.test(v.lang+' '+v.name); }); if(!pool.length) pool=vs; for(var i=0;i<VPREF.length;i++){ var m=pool.filter(function(v){ return VPREF[i].test(v.name); })[0]; if(m) return m; } return pool[0]||null; }
window.PWpickVoice=pickVoice;
function say(t){ t=cleanSpeech(t); if(!t) return; if(!('speechSynthesis' in window)||SND.on===false) return; try{ window.speechSynthesis.cancel(); var u=new SpeechSynthesisUtterance(t); u.rate=0.95; u.pitch=1.3; u.volume=1; var v=pickVoice(); if(v){ u.voice=v; u.lang=v.lang; } else u.lang='en-US'; window.speechSynthesis.speak(u); }catch(e){} }
function giggle(){ if(SND.on===false) return; try{ var c=SND.ac&&SND.ac(); if(!c) return; [880,1040,880,1040,780].forEach(function(f,i){ var o=c.createOscillator(),g=c.createGain(); o.type='sine'; o.frequency.value=f; var t0=c.currentTime+i*.11; g.gain.setValueAtTime(.0001,t0); g.gain.exponentialRampToValueAtTime(.05,t0+.02); g.gain.exponentialRampToValueAtTime(.0001,t0+.1); o.connect(g); g.connect(c.destination); o.start(t0); o.stop(t0+.12); }); }catch(e){} }
function laugh(){ setFace('silly'); giggle(); var m=mini.classList.contains('on')?mini:(big.classList.contains('on')?big:null); if(m&&!reduced){ m.style.animation='pxlaugh .18s ease-in-out 8'; setTimeout(function(){ m.style.animation=''; },1500); } setTimeout(function(){ setFace('happy'); },1800); }
window.PWlaugh=laugh;
/* Browsers refuse to speak until the child has tapped or pressed something. Hold the words and say them at the first touch. */
var unlocked=false, pendingSay=null;
function unlock(){ if(unlocked) return; unlocked=true; if(pendingSay&&(bub.classList.contains('on')||big.classList.contains('on'))){ var t=pendingSay; pendingSay=null; say(t); } pendingSay=null; }
['pointerdown','keydown','touchstart'].forEach(function(ev){ D.addEventListener(ev,unlock,{capture:true,passive:true}); });
function sayBub(t){ if(unlocked) say(t); else pendingSay=t; }
function bubble(txt,who){ var b=H('div',{'class':'pxb '+who,text:txt},log); log.scrollTop=log.scrollHeight; return b; }
function her(txt,delay){ setTimeout(function(){ bubble(txt,'her'); say(txt); setFace('talk'); clearTimeout(her.t); her.t=setTimeout(function(){ setFace('happy'); },Math.min(6000,1200+txt.length*55)); },delay||0); }
